"""Password hashing and session-token helpers.

Two different kinds of secret pass through this file, and each is protected in
a deliberately different way:

* **Passwords** are chosen by humans, so they are short, predictable and often
  reused across sites. They get bcrypt: a hash that is *slow on purpose*, so an
  attacker who steals the database can only test a few thousand guesses per
  second instead of billions.

* **Session tokens** are generated by us from 32 random bytes. There is nothing
  to guess: brute-forcing 256 bits of entropy is not a thing. They get SHA-256,
  which is fast -- and it has to be fast, because it runs on every single
  authenticated request. Using bcrypt here would add ~250 ms to every page load
  for no security gain at all.

Nothing in this file touches the database or FastAPI. Keeping it dependency-free
means it can be unit-tested on its own.
"""
import hashlib
import secrets
from datetime import datetime, timedelta, timezone

import bcrypt

from app.config import settings

# bcrypt only looks at the first 72 BYTES of a password and ignores the rest.
# It does so silently, which means "correct horse battery staple ..." truncated
# at byte 72 would still log the user in. We refuse anything longer instead, so
# the user gets a clear error rather than a password that is secretly shorter
# than they think. Note: BYTES, not characters -- an accented "ã" costs 2 bytes
# in UTF-8, an emoji costs 4.
MAX_PASSWORD_BYTES = 72

# 32 bytes = 256 bits of randomness for each session token. For comparison, a
# UUID4 has 122 bits. This is far beyond anything guessable.
SESSION_TOKEN_BYTES = 32


# ---------------------------------------------------------------------------
# Time helper
# ---------------------------------------------------------------------------
def utcnow() -> datetime:
    """Current UTC time as a *naive* datetime (no tzinfo attached).

    MariaDB's DATETIME/TIMESTAMP columns store no timezone, and PyMySQL cannot
    serialise a timezone-aware datetime into them. So we compute the time in
    UTC (correct) and then drop the tzinfo (compatible). Every datetime written
    to or compared against the database goes through this function, so
    everything in the DB is UTC and comparisons are always apples to apples.
    """
    return datetime.now(timezone.utc).replace(tzinfo=None)


# ---------------------------------------------------------------------------
# Passwords
# ---------------------------------------------------------------------------
def hash_password(plain: str) -> str:
    """Turn a plaintext password into a bcrypt hash ready to store.

    ``gensalt()`` produces a fresh random salt every time, which is why hashing
    the same password twice gives two different results. That is the whole
    point of a salt: an attacker cannot build one table of pre-computed hashes
    and crack every account at once -- each password has to be attacked alone.

    The salt is not stored separately: bcrypt packs everything into the 60-char
    output string, e.g. ``$2b$12$<22 chars of salt><31 chars of hash>``, where
    ``2b`` is the bcrypt variant and ``12`` is the cost factor (the hash runs
    2^12 rounds internally -- raise the number and it gets exponentially
    slower for both us and the attacker).
    """
    encoded = plain.encode("utf-8")
    if len(encoded) > MAX_PASSWORD_BYTES:
        raise ValueError(
            f"password must not exceed {MAX_PASSWORD_BYTES} bytes when encoded as UTF-8"
        )
    # bcrypt works on bytes; the database column holds text, hence the decode.
    return bcrypt.hashpw(encoded, bcrypt.gensalt(rounds=settings.bcrypt_rounds)).decode("utf-8")


def verify_password(plain: str, stored_hash: str) -> bool:
    """Check a login attempt against the hash we have on file.

    bcrypt reads the salt and the cost factor back out of ``stored_hash``,
    re-hashes ``plain`` with them, and compares the two results in constant
    time -- meaning the comparison always takes the same amount of time whether
    it fails on the first byte or the last. A naive ``==`` would return faster
    on an early mismatch, and that timing difference is enough to leak the hash
    one byte at a time.

    Returns False instead of raising on malformed input: a single corrupted row
    should fail that one login, not crash the endpoint with a 500.
    """
    try:
        return bcrypt.checkpw(plain.encode("utf-8"), stored_hash.encode("utf-8"))
    except (ValueError, TypeError):
        return False


# ---------------------------------------------------------------------------
# Session tokens
# ---------------------------------------------------------------------------
def generate_session_token() -> str:
    """Create a brand-new random session token (the value the browser gets).

    ``secrets`` is the cryptographically secure random generator -- unlike
    ``random``, whose output is predictable if you observe enough of it.
    ``token_urlsafe`` gives base64 text safe to put straight into a cookie.

    This is the ONLY moment the raw token exists on our side. We hand it to the
    browser and store only its hash (see below).
    """
    return secrets.token_urlsafe(SESSION_TOKEN_BYTES)


def hash_session_token(raw_token: str) -> str:
    """Hash a session token for storage and lookup.

    Why hash it at all? Because the tokens table is a table of live passwords:
    anyone who reads it could paste a token into their own cookie and be logged
    in as that user, no password needed. Storing only hashes means a leaked
    database dump grants nothing.

    SHA-256 (fast) rather than bcrypt (slow) is the right call here -- see the
    reasoning in this module's docstring. Same input always gives the same
    output, which is what lets us find the session row with a plain indexed
    ``WHERE token_hash = ...`` lookup.
    """
    return hashlib.sha256(raw_token.encode("utf-8")).hexdigest()


def session_expiry() -> datetime:
    """When a session created right now should stop being accepted.

    Stored on the row so that expiry is enforced server-side. Trusting the
    cookie's own expiry date would be pointless -- the browser owns that value
    and the user can edit it.
    """
    return utcnow() + timedelta(hours=settings.session_ttl_hours)


def is_session_active(
    expires_at: datetime, now: datetime | None = None
) -> bool:
    """Return whether a session is still valid at the given UTC instant."""
    return expires_at > (now or utcnow())
